-- PAPER-LEARN-PROBATION-SETTLE-1 part 5 of 9 (2026-11-05, charter pillar autonomy, program QNFO.OPS; cluster C8-PROJECTS-GOALS of the roadmap and backlog completion sweep).
-- Settles 25 probationary direct paper learnings (ids 5067 to 5225 of the 225 read on 2026-11-04 23:00Z): each row was read in full (claim, lever, application and the model's apply signal) against the live fleet and given one disposition with its reason.
-- PAPER-LEARN-TRIAGE-1 parked them in probation because its catalogue held 6 mechanisms; the apply signal usually meant the model did not know the fleet already does this. Dispositions: already-in-place (mechanism named, existence read today), rejected (category and specific reason, with what would justify re-proposing), routed (to agent_issues 1000459 TRIGGER-FLAP-1 or goal external-impact-per-dollar).
-- Each goal PAPER-LEARN-<id> (DoD: the learning is settled) then completes on its next probe, and roadmap row GL-PAPER-LEARN-<id> verifies in the hourly loop. Revert one row: UPDATE paper_learnings SET fleet_status = 'probation' WHERE id = <id>.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE paper_learnings SET fleet_status = (SELECT b.fleet_status FROM bak_20261105_c8_pl_05 b WHERE b.id = paper_learnings.id), status_note = (SELECT b.status_note FROM bak_20261105_c8_pl_05 b WHERE b.id = paper_learnings.id), updated_at = (SELECT b.updated_at FROM bak_20261105_c8_pl_05 b WHERE b.id = paper_learnings.id) WHERE id IN (SELECT id FROM bak_20261105_c8_pl_05)

CREATE TABLE IF NOT EXISTS bak_20261105_c8_pl_05 AS SELECT * FROM paper_learnings WHERE id IN (5067, 5068, 5075, 5076, 5095, 5096, 5097, 5099, 5100, 5105, 5144, 5178, 5184, 5185, 5186, 5187, 5189, 5204, 5205, 5206, 5208, 5209, 5211, 5224, 5225);

UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; caps): Loops are capped per run instead of failing at a wall: remediation_contracts carries max_items and budget_ms, workflows carry timeout_ms 120000, and loops such as PL_TRIAGE_EXAMINE (12 per tick) bound their batch.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5067 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; paper-convention): A fidelity label (synthetic analog versus end-to-end validated) is this paper''s own limitation statement; the pipeline states AI involvement in each paper''s provenance section and CLAIM-INTEGRITY-1 holds unsupported empirical claims. Re-propose with a downstream consumer that treated a synthetic analog as validated.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5068 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; relapse): A bounded observation does not close an issue for good: a closed issue is refiled and reopened on relapse (issue_refile_reopen), the close hold is judged on the channel it governs (RELAPSE-COHORT-2, #7171), and a probe re-runs on its cadence.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5075 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Finite-tree radii below the infinite-tree radius is the paper''s spectral result; the fleet sets thresholds from measured values in analytics_metric_triggers and ledger scope from verified outcomes, so no theoretical-capacity bound is used. Re-propose with a threshold copied from a nominal bound.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5076 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; claimintegrity): Evidence the paper itself labels simulated cannot be presented as empirical verification: CLAIM-INTEGRITY-1 (ops_config claim_integrity_mode = enforce, read 2026-11-05) holds or rewrites past-tense empirical claims the work does not support, and the independent reviewer reads each paper.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5095 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; trigger-flap): Routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, critical, qnfo-fleet-control): it is the period-2 close-then-reopen cycle (167 reopens on 44 METRIC-TRIGGER tickets in 7 days) with the typed hold the learning proposes.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5096 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; caps): Iteration caps exist inside loops: qnfo-research-exec bounds no-op revisions (REVISE_NOOP_MAX = 2), loops bound batches per tick (PL_TRIAGE_EXAMINE = 12) and contracts bound attempts (max_attempts); research-backpressure bounds the ready queue.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5097 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; modeleval): Both arms run the same fixed battery through one harness: qnfo-model-eval benchmarks each candidate against the production control with automatic revert, and the benchmark rows are kept in cf_model_eval_runs.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5099 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; invalidclass): Malformed input already gets its own issue class instead of a retry: PROBE-NEEDED-1, CODE-MERGE-REFUSED-1 and CODE-LOOP-EXHAUSTED-1 are distinct ticket families (CLAUDE.md issue hygiene), probe text is normalised by the remediation_probe_semicolon triggers and worker-load-gate and code-anchor-once fail a pull request on a malformed entry.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5100 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Fleet metrics are computed in SQL over the full table with the window named in the metric (7d, 30d), not over a sampled or truncated series, and no breach is shown to have come from a truncated window. Re-propose with such a breach.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5105 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): A missing comparison arm in one cited paper is a point about that paper''s reporting; the fleet''s own benchmarks (qnfo-model-eval) run every arm on one battery and the pipeline reviewer reads each paper''s comparisons.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5144 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; cost): Fixed and idle cost is already in the ledger: v_cost_all_in sums 25 cost lines across vendors (measured 1196.97 USD, owner-stated 450 USD, month-to-date 160.28 USD read 2026-11-05), not only per-call AI spend.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5178 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Tagging each trust-ledger entry with the operating range of its model is the paper''s regime-of-validity point for linearization; the ledger widens only fleet loop scopes from verified outcomes and no widening is shown to have been applied outside the conditions it was verified in. Re-propose with one.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5184 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; bands): Proximity-to-boundary signalling exists: metric_registry carries a warning_band on 333 of 418 metrics and a kill_band on 257 (read 2026-11-05), so a metric alerts before its breach threshold.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5185 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; registry): Each registered metric states what it measures and from where: metric_registry requires a formula and source_of_truth (insert refused without them), and METRIC-CAUSE-AT-REGISTRATION-1 maps its breach cause.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5186 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; watchdog): Watchdogs over the primary controllers exist: LOOP-WATCH-1 (qnfo-fleet-control /loops) files and self-closes loop-stale issues, the cron-watch task reads cron faults every cycle, and each failure mode has an fm-<key> detector contract.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5187 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): The cubic error term of a linearization is the paper''s mathematics; fleet thresholds are set from measured values with warning and kill bands (333 and 257 of 418 metrics), and no breach is shown to come from a flat margin that ignored a known error curve.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5189 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; caps): The code loop''s generation rate is bounded by what review can absorb: the assignment sweep never lets more than 12 Copilot pull requests be open org-wide (CLAUDE.md ASSIGN-COPILOT-ISSUES-1), code-loop merges wait for green checks and the review gate, and queued code tasks on one file are batched into one proposal (CODE-BATCH-SAMEFILE-1).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5204 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; maxatt): Cumulative drift inside a loop is bounded: remediation_contracts.max_attempts parks an over-retried contract, CODE-LOOP-EXHAUSTED-1 files a ticket when the code loop spends its tries, and a control-plane change that fails its canary is reverted (canary_revert.py).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5205 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; merge): Review effort already scales with the change: scripts/review_gate.py classifies a diff by what it touches, reads only risky ones with two disjoint families, splits and fits a large diff into chunks (REVIEW-GATE-1 v2, #7243) and holds only when both families report the finding.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5206 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; canary): Consensus is anchored to execution, not to agreement: DEPLOY-PROBES-1 runs declared routes and D1 statements before and after a deploy and reverts a regression, remediation probes read live state, and the review gate accepts a finding only when its evidence is an added line of the diff.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5208 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; trigger-flap): Routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, critical, qnfo-fleet-control): replacing bare flat-line thresholds with bands that tolerate bounded oscillation is the fix that issue applies to METRIC-TRIGGER tickets closing and reopening in a loop.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5209 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; claims): Claims already carry freshness and are invalidated: a work claim expires after at most ttl_sec 7200 and returns a fence counter, an expired claim with the work undone is taken over (OWNER-NO-LOOSE-ENDS-1), and a green pull request is merged only against its current head.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5211 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; trigger-flap): Routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, critical, qnfo-fleet-control): firing a metric trigger only after several observation windows agree (a run length and a band) is the fix that issue applies against 167 reopens on 44 tickets in 7 days.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5224 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): Exact integrated information being NP-hard is a fact about a consciousness measure; the fleet computes no integration metric over its whole self, and the cohesion checks it does run (fleet graph findings, issue accounting) are cheap SQL reconciliations.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5225 AND fleet_status = 'probation';
